const isDot = (num) => {
    if (num) {
        let result = (num.toString()).indexOf(".")
        if (result != -1) {
            let t1 = Math.trunc(num)
            let t = t1.toString().replace(/(\d)(?=(?:\d{3})+$)/g, "$1,")
            return t
        } else {
            let t1 = Math.trunc(num)
            let t = t1.toString().replace(/(\d)(?=(?:\d{3})+$)/g, "$1,")
            return t
        }
    } else {
        return 0
    }
}

const numDot = (num) => {
