const sort = (type, lotId) => {
    sort_type.value = type
    if (orderby.value == '') {
        orderby.value = 'asc'
    } else if (orderby.value == 'asc') {
        orderby.value = 'desc'
    } else {
        orderby.value = ''
    }

    lot_id.value = lotId ? lotId : ''
    params.value.game_id = lot_id.value
    params.value.orderby = orderby.value
    params.value.sort_type = sort_type.value

    function compare(key, type) {
        return function (value1, value2) {
            var val1 = value1[key] * 1
            var val2 = value2[key] * 1

            if (type == 'asc') {
                if (val2 < val1) {
                    return 1
                } else if (val2 > val1) {
                    return -1
                } else {
                    return 0
                }
            } else {
                if (val2 > val1) {
                    return 1
                } else if (val2 < val1) {
                    return -1
                } else {
                    return 0
                }
            }
        }
    }

    let sortType = { 1: 'count', 2: 'betAmount', 3: 'belongReceivable', 4: 'deliveryResult' }
    let that = this
    if (lot_id.value) {
        billinghandan.value = Object.values(billinghandan.value).map(item => {
            if (lot_id.value == item.lotteryId) {
                item.billing = Object.values(item.omsOrders).sort(compare(sortType[type], orderby.value))
            }
            return item
        })
        billinghandan.value = JSON.parse(JSON.stringify(billinghandan.value))
    } else {
        reportList.value = Object.values(reportList.value).sort(compare(sortType[type], orderby.value))
        reportList.value = JSON.parse(JSON.stringify(reportList.value))
    }
}

