const getReportList = async () => {
    const loading = showLoadingToast({
        lock: true,
        duration: 0,
        forbidClick: true,
        mask: true,
        message: '正在加载……'
    })
    try {
        const res = await userStore.getSettlement(params.value)
        loading.close()
        reportList.value = res.data ? res.data[0].omsOrders : []
        if (route.params.account) {
            role.value = res.data[0].prole
        }
        sumCount()
    } catch (error) {
        loading.close()
        console.error(error)
    }
}

