    logInfo.value = ust
    const storedItem = JSON.parse(localStorage.getItem('agreportForm'));
    if (Object.keys(storedItem).length == 0) {
        router.push('/ReportQuery')
        return
    }
    window.scrollTo({
        top: 0,
        behavior: 'smooth'
    })
    hisParm.value = storedItem
    params.value = storedItem
    role.value = ust.layer
    getReportList()
    getwzList(ust.id)
